const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function isRetryable(error) {
  const status = error && error.status;
  if (typeof status !== 'number') return true; // network failure, timeout
  if (status === 408 || status === 429) return true;
  return status < 400 || status >= 500;
}

async function withRetry(task, { retries = 2, baseDelayMs = 1000, sleep = wait } = {}) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await task(attempt);
    } catch (error) {
      if (attempt > retries || !isRetryable(error)) throw error;
      await sleep(baseDelayMs * 2 ** (attempt - 1));
    }
  }
}

let calls = 0;
const flaky = async () => {
  calls += 1;
  if (calls < 3) throw Object.assign(new Error('Service unavailable'), { status: 503 });
  return ['Ridge Loop', 'Lake Trail'];
};
withRetry(flaky, { baseDelayMs: 10 }).then((v) => console.log('got', v, 'after', calls, 'calls'), (e) => console.log('failed:', e.message));
